//! Port of `src/test/java/com/google/devtools/build/lib/analysis/starlark/ArgsParamFileTest.java`.
//!
//! Each test checks the intermediate argument string list generated from the same `Args` with a
//! different param file format. The param file would be generated by writing one argument per
//! line, possibly after filtering out the positional args.
//!
//! PORT: Java builds the `Args` by calling `Args.addJoined`/`addArgument`/`addAll` from Java;
//! here the same calls are made from Starlark (the methods are only reachable through Starlark),
//! and the module is frozen before the command line is built.

use std::sync::Arc;

use blaze_actions::actions::action_key_context::ActionKeyContext;
use blaze_actions::actions::parameter_file::write_parameter_file;
use blaze_actions::actions::path_mapper::OutputPathsMode;
use blaze_actions::analysis::starlark::args::{BuiltArgs, build_args, new_args};
use blaze_cmdline::RepositoryMapping;
use blaze_shell::util::shell_escaper::ShellEscaper;
use blaze_starlark::eval::{EvalOptions, compile, exec_module};
use blaze_starlark::loader::LoadMap;
use blaze_starlark::thread::{CollectingEvents, Phase, ThreadContext};
use blaze_starlark::{EvalError, FileKind, StarlarkSemantics};
use blaze_util::Fingerprint;
use starlark::environment::GlobalsBuilder;
use starlark::eval::Evaluator;
use starlark::starlark_module;
use starlark::values::{OwnedFrozenValue, Value};

/// Test-only global standing in for `ctx.actions.args()`.
#[starlark_module]
fn test_natives(builder: &mut GlobalsBuilder) {
    fn make_args<'v>(eval: &mut Evaluator<'v, '_, '_>) -> starlark::Result<Value<'v>> {
        let semantics = ThreadContext::get(eval)?.semantics.clone();
        Ok(new_args(eval.heap(), semantics))
    }
}

/// Initializes args with a mix of "flags" and "positional arguments".
// Java: ArgsParamFileTest.initArgs
const INIT_ARGS: &str = r#"
args = make_args()
args.add_joined(
    "--a",
    ["b", "c"],
    join_with = ",",
    omit_if_empty = False,
    uniquify = False,
    expand_directories = False,
    allow_closure = False,
)
args.add("--nod")
args.add("pos1")
args.add_all(
    "--foo",
    ["bar1", "bar2", "bar3"],
    omit_if_empty = False,
    uniquify = False,
    expand_directories = False,
    allow_closure = False,
)
args.add("--e", "'f'")
args.add("pos2")
# Ensure a ParamFileInfo will be returned
args.use_param_file("%s", use_always = True)
"#;

/// Evaluates `INIT_ARGS` followed by `extra` and returns the frozen `args` value.
fn eval_args(extra: &str) -> Result<OwnedFrozenValue, EvalError> {
    eval_script(&format!("{INIT_ARGS}{extra}"))
}

/// Evaluates `code` and returns its frozen global `args`.
fn eval_script(code: &str) -> Result<OwnedFrozenValue, EvalError> {
    let semantics = Arc::new(StarlarkSemantics::default());
    let globals = blaze_starlark::env::universe_builder(&semantics)
        .with(blaze_starlark::depset::register_depset)
        .with(test_natives)
        .build();
    let compiled = compile(FileKind::Bzl, "test/args.bzl", code.to_owned())?;
    let ctx = ThreadContext::new(
        Phase::BzlLoad,
        semantics,
        Arc::new(CollectingEvents::default()),
    );
    let module = exec_module(
        compiled,
        &globals,
        &LoadMap::new(),
        &ctx,
        &EvalOptions::default(),
    )?;
    Ok(module.get("args").unwrap())
}

fn build(args: &OwnedFrozenValue) -> BuiltArgs {
    build_args(args, &mut || -> RepositoryMapping {
        (*blaze_cmdline::repository_mapping::EMPTY).clone()
    })
    .unwrap()
}

/// Writes out the Args using ParameterFile, returns the output broken down as lines. Note, this
/// does not respect `ParamFileInfo.flagsOnly()`.
// Java: ArgsParamFileTest.toParamFile
fn to_param_file(args: &BuiltArgs) -> Vec<String> {
    let arguments = args.command_line.arguments().unwrap();
    let mut bytes: Vec<u8> = Vec::new();
    write_parameter_file(&mut bytes, &arguments, args.parameter_file_type).unwrap();
    String::from_utf8(bytes)
        .unwrap()
        .lines()
        .map(str::to_owned)
        .collect()
}

#[test]
fn bad_param_file_format() {
    let e = eval_args("args.set_param_file_format(\"punch_cards\")\n").unwrap_err();
    assert!(
        e.message.contains(
            "Invalid value for parameter \"format\": Expected one of \"shell\", \"multiline\", \
             \"flag_per_line\""
        ),
        "{}",
        e.message
    );
}

#[test]
fn set_param_file_format_twice() {
    let e =
        eval_args("args.set_param_file_format(\"shell\")\nargs.set_param_file_format(\"shell\")\n")
            .unwrap_err();
    assert!(
        e.message
            .contains("set_param_file_format() may only be called once"),
        "{}",
        e.message
    );
}

#[test]
fn shell() {
    let args = build(&eval_args("args.set_param_file_format(\"shell\")\n").unwrap());
    let escaped_f = ShellEscaper::escape_string("'f'");
    assert_eq!(
        to_param_file(&args),
        vec![
            "--a",
            "b,c",
            "--nod",
            "pos1",
            "--foo",
            "bar1",
            "bar2",
            "bar3",
            "--e",
            escaped_f.as_str(),
            "pos2",
        ]
    );
    assert!(!args.param_file_info.unwrap().flags_only());
}

#[test]
fn multiline() {
    let args = build(&eval_args("args.set_param_file_format(\"multiline\")\n").unwrap());
    assert_eq!(
        to_param_file(&args),
        vec![
            "--a", "b,c", "--nod", "pos1", "--foo", "bar1", "bar2", "bar3", "--e", "'f'", "pos2",
        ]
    );
    assert!(!args.param_file_info.unwrap().flags_only());
}

#[test]
fn flag_per_line() {
    let args = build(&eval_args("args.set_param_file_format(\"flag_per_line\")\n").unwrap());
    assert_eq!(
        to_param_file(&args),
        vec![
            "--a=b,c",
            "--nod",
            "pos1",
            "--foo=bar1 bar2 bar3",
            "--e='f'",
            "pos2",
        ]
    );
    assert!(args.param_file_info.unwrap().flags_only());
}

// Not a Java test: `map_each` over a depset and a list, called after the module is frozen, and
// fingerprinting through the nested set cache.
#[test]
fn map_each_after_freezing() {
    let args = build(
        &eval_script(
            r#"
def fmt(x):
    return "-I" + x

args = make_args()
args.add_all(depset(["a", "b"]), map_each = fmt)
args.add_joined(["c", "d"], join_with = ":", map_each = fmt, format_joined = "--path=%s")
"#,
        )
        .unwrap(),
    );
    assert_eq!(
        args.command_line.arguments().unwrap(),
        vec!["-Ia", "-Ib", "--path=-Ic:-Id"]
    );
    let mut fingerprint = Fingerprint::new();
    args.command_line
        .add_to_fingerprint(
            &ActionKeyContext::new(),
            None,
            OutputPathsMode::OFF,
            &mut fingerprint,
        )
        .unwrap();
    assert!(args.param_file_info.is_none());
}

// Not a Java test: Args.add rejects vectorized values (Args.java:312).
#[test]
fn add_rejects_vectorized_arguments() {
    let e = eval_script("args = make_args()\nargs.add([\"a\"])\n").unwrap_err();
    assert!(
        e.message.contains(
            "Args.add() doesn't accept vectorized arguments. Please use Args.add_all() or \
             Args.add_joined() instead."
        ),
        "{}",
        e.message
    );
}
